SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- Matching: city boundaries, the admin matching config, invites to apply, and invite alerts.
-- Expand step. The new CHECKs are added NOT VALID and validated in 20261128000200_matching_validate.

-- A city is the hard limit for home tuition: the student's pin is inside the boundary, and the tutor
-- lives inside it or within matching_config.cityEdgeKm of its edge (or has a zone there).
-- Dhaka is seeded from the OpenStreetMap "Dhaka Metropolitan" boundary (relation 13663697,
-- admin_level 6; © OpenStreetMap contributors, ODbL). Admins can upload the other cities.
CREATE TABLE "city" (
    "slug" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "district_code" TEXT NOT NULL,
    "boundary" GEOGRAPHY(MULTIPOLYGON, 4326) NOT NULL,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "city_pkey" PRIMARY KEY ("slug"),
    CONSTRAINT "city_slug_format" CHECK ("slug" ~ '^[a-z][a-z0-9-]{1,39}$'),
    CONSTRAINT "city_name_len" CHECK (length(btrim("name")) BETWEEN 2 AND 60)
);

-- New, empty table: CONCURRENTLY cannot run inside the migration transaction, and nothing is locked.
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX "city_boundary_gix" ON "city" USING GIST ("boundary");

