-- A student asks a tutor to apply to one of their requirements. One invite per pair.
CREATE TABLE "requirement_invite" (
    "id" UUID NOT NULL,
    "requirement_id" UUID NOT NULL,
    "tutor_id" UUID NOT NULL,
    "student_id" UUID NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "requirement_invite_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "requirement_invite_requirement_id_fkey" FOREIGN KEY ("requirement_id") REFERENCES "tuition_requirement"("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "requirement_invite_tutor_id_fkey" FOREIGN KEY ("tutor_id") REFERENCES "tutor"("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "requirement_invite_student_id_fkey" FOREIGN KEY ("student_id") REFERENCES "student"("id") ON DELETE CASCADE ON UPDATE CASCADE
);

-- squawk-ignore require-concurrent-index-creation
CREATE UNIQUE INDEX "requirement_invite_requirement_id_tutor_id_key" ON "requirement_invite"("requirement_id", "tutor_id");
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX "requirement_invite_tutor_id_created_at_idx" ON "requirement_invite"("tutor_id", "created_at" DESC);
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX "requirement_invite_student_id_idx" ON "requirement_invite"("student_id");

-- New values are only used by later transactions, which PostgreSQL 12+ allows inside one migration.
ALTER TYPE "AppNotificationKind" ADD VALUE 'REQUIREMENT_INVITED' AFTER 'UPLOADS_UNBLOCKED';

-- Invite alerts name a requirement, not an application. Existing rows get NULL.
ALTER TABLE "app_notification" ADD COLUMN "requirement_id" UUID;
ALTER TABLE "app_notification" ADD CONSTRAINT "app_notification_requirement_id_fkey" FOREIGN KEY ("requirement_id") REFERENCES "tuition_requirement"("id") ON DELETE CASCADE ON UPDATE CASCADE NOT VALID;
-- app_notification is small (one row per application event); the brief lock is accepted, as for the
-- columns added in 20261126000100_upload_moderation.
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX "app_notification_requirement_id_idx" ON "app_notification"("requirement_id");
ALTER TABLE "app_notification" ADD CONSTRAINT "app_notification_requirement_shape" CHECK (
  (requirement_id IS NOT NULL) = (kind::text = 'REQUIREMENT_INVITED')
) NOT VALID;

-- platform_setting gains matching_config, a JSON object validated by the API (matching-config.ts).
-- The CASE has no branch for a new key, so the CHECK is replaced; existing rows are re-checked in the
-- validate migration.
-- squawk-ignore ban-drop-constraint
ALTER TABLE "platform_setting" DROP CONSTRAINT "platform_setting_value_valid";
ALTER TABLE "platform_setting" ADD CONSTRAINT "platform_setting_value_valid" CHECK (
  CASE key
    WHEN 'require_tutor_verification' THEN jsonb_typeof(value) = 'boolean'
    WHEN 'require_tutor_phone_verification' THEN jsonb_typeof(value) = 'boolean'
    WHEN 'require_student_phone_verification' THEN jsonb_typeof(value) = 'boolean'
    WHEN 'online_payments_enabled' THEN jsonb_typeof(value) = 'boolean'
    WHEN 'commission_percent' THEN
      CASE WHEN jsonb_typeof(value) = 'number' THEN (value #>> '{}')::numeric BETWEEN 0 AND 100 ELSE false END
    WHEN 'gateway_charge_percent' THEN
      CASE WHEN jsonb_typeof(value) = 'number' THEN (value #>> '{}')::numeric BETWEEN 0 AND 10 ELSE false END
    WHEN 'refund_window_days' THEN
      CASE WHEN jsonb_typeof(value) = 'number'
        THEN (value #>> '{}')::numeric BETWEEN 0 AND 90 AND (value #>> '{}')::numeric = trunc((value #>> '{}')::numeric)
        ELSE false END
    WHEN 'matching_config' THEN jsonb_typeof(value) = 'object'
    ELSE false
  END) NOT VALID;
